#define MATRIX_SIZE 2048
int data[MATRIX_SIZE][MATRIX_SIZE];

// --- High Spatial Locality (Cache Hit optimized) ---
// Accessing sequentially (row-major storage)
for (int i = 0; i < MATRIX_SIZE; i++) {
    for (int j = 0; j < MATRIX_SIZE; j++) {
        data[i][j] = 1; // Uses elements adjacent in memory
    }
}

// --- Low Spatial Locality (Cache Miss heavy) ---
// Accessing non-sequentially (column traversal)
// Stride is MATRIX_SIZE * sizeof(int)
for (int j = 0; j < MATRIX_SIZE; j++) {
    for (int i = 0; i < MATRIX_SIZE; i++) {
        data[i][j] = 2; // Cache line must be reloaded often
    }
}
